// Renders docs/handbook/*.md and the templates/ files into
// src/site/handbook-content.ts, so the website shows exactly the text kept in
// the repository. Run `npm run handbook` after editing; a test fails if the
// generated file is out of date.
import { readdirSync, readFileSync, writeFileSync } from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'

import { Marked } from 'marked'

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..')
const OUT = path.join(root, 'src/site/handbook-content.ts')

// Order of the handbook pages in navigation.
const ORDER = ['index', 'volunteers', 'organizations', 'work-packages', 'what-is-github', 'secure-your-repository', 'safety-and-quality', 'what-happens-when', 'github-best-practice', 'open-source']

const TEMPLATES = [
  ['volunteer-compute.yaml', 'The task list, at the root of your repository.'],
  ['AGENTS.md', 'The rules every volunteer\'s AI reads before each task.'],
  ['.github/CODEOWNERS', 'Who must review which files.'],
  ['.github/workflows/tests.yml', 'Tests on every pull request, without secrets.'],
  ['.github/pull_request_template.md', 'The same record for pull requests opened by people.'],
]

const slug = (text) => text.toLowerCase().replace(/<[^>]+>/g, '').replace(/&[a-z#0-9]+;/g, '').replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '')
const escapeHtml = (s) => s.replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c])

function renderer() {
  const marked = new Marked({ gfm: true })
  marked.use({
    renderer: {
      heading({ tokens, depth }) {
        const text = this.parser.parseInline(tokens)
        if (depth === 1) return `<h1>${text}</h1>\n`
        return `<h${depth} id="${slug(text)}">${text}</h${depth}>\n`
      },
      table(token) {
        const head = token.header.map((cell) => `<th scope="col">${this.parser.parseInline(cell.tokens)}</th>`).join('')
        const rows = token.rows.map((row) => `<tr>${row.map((cell) => `<td>${this.parser.parseInline(cell.tokens)}</td>`).join('')}</tr>`).join('\n')
        return `<div class="table-scroll" tabindex="0"><table><thead><tr>${head}</tr></thead><tbody>${rows}</tbody></table></div>\n`
      },
      link({ href, tokens }) {
        const text = this.parser.parseInline(tokens)
        const external = /^https?:\/\//.test(href)
        return `<a href="${escapeHtml(href)}"${external ? ' rel="noopener"' : ''}>${text}</a>`
      },
      listitem(item) {
        const body = this.parser.parse(item.tokens, !!item.loose)
        if (item.task) return `<li class="todo-item"><span class="box" aria-hidden="true"></span>${body.replace(/^<input[^>]*> ?/, '')}</li>\n`
        return `<li>${body}</li>\n`
      },
    },
  })
  return marked
}

function frontmatter(source) {
  const match = source.match(/^---\n([\s\S]*?)\n---\n/)
  if (!match) throw new Error('missing frontmatter')
  const meta = Object.fromEntries(match[1].split('\n').map((line) => {
    const at = line.indexOf(':')
    return [line.slice(0, at).trim(), line.slice(at + 1).trim()]
  }))
  return { meta, body: source.slice(match[0].length) }
}

export function buildHandbook() {
  const marked = renderer()
  const dir = path.join(root, 'docs/handbook')
  const files = readdirSync(dir).filter((f) => f.endsWith('.md'))
  const missing = ORDER.filter((name) => !files.includes(`${name}.md`))
  if (missing.length) throw new Error(`handbook pages missing: ${missing.join(', ')}`)
  const pages = ORDER.map((name) => {
    const { meta, body } = frontmatter(readFileSync(path.join(dir, `${name}.md`), 'utf8'))
    const html = marked.parse(body)
    const toc = [...body.matchAll(/^## (.+)$/gm)].map((m) => ({ id: slug(marked.parseInline(m[1])), text: m[1].replace(/[*`]/g, '') }))
    return { slug: name === 'index' ? '' : name, title: meta.title, description: meta.description, html, toc, source: `docs/handbook/${name}.md` }
  })
  const templates = TEMPLATES.map(([file, note]) => ({ file, note, content: readFileSync(path.join(root, 'templates', file), 'utf8') }))
  return `// Generated by scripts/build-handbook.mjs from docs/handbook/ and templates/. Do not edit.\n\nexport type HandbookPage = { slug: string; title: string; description: string; html: string; toc: { id: string; text: string }[]; source: string }\n\nexport const HANDBOOK: HandbookPage[] = ${JSON.stringify(pages, null, 2)}\n\nexport const TEMPLATES: { file: string; note: string; content: string }[] = ${JSON.stringify(templates, null, 2)}\n`
}

if (process.argv[1] && fileURLToPath(import.meta.url) === path.resolve(process.argv[1])) {
  writeFileSync(OUT, buildHandbook())
  console.log(`wrote ${path.relative(root, OUT)}`)
}
